const lead = $('On form submission').first().json;
const MAX_PAGES = 10;

function parse(raw) {
  const m = String(raw).match(/^(https?):\/\/([^\/?#]+)([^?#]*)/i);
  if (!m) return null;
  return {
    protocol: m[1].toLowerCase(),
    host: m[2].toLowerCase().replace(/^www\./, ''),
    path: m[3] || '/'
  };
}

// turn any href (absolute or relative) into a full URL
function resolve(href, base) {
  href = String(href).trim();
  if (!href || /^(#|mailto:|tel:|sms:|javascript:|data:|whatsapp:)/i.test(href)) return null;
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return base.protocol + ':' + href;

  const origin = base.protocol + '://' + base.host;
  if (href.startsWith('/')) return origin + href;

  // relative to the current folder, e.g. "about.html" or "../about"
  const dir = base.path.replace(/[^\/]*$/, '');
  const parts = [];
  for (const seg of (dir + href).split(/[?#]/)[0].split('/')) {
    if (seg === '..') { if (parts.length > 1) parts.pop(); }
    else if (seg !== '.') parts.push(seg);
  }
  return origin + parts.join('/');
}

const site = parse(lead.website_url);
if (!site) throw new Error('Invalid website_url: ' + lead.website_url);

const d = $input.first().json.data || $input.first().json;
const finalUrl = parse(d.metadata?.url || d.metadata?.sourceURL || lead.website_url) || site;
const hosts = new Set([site.host, finalUrl.host]);   // accept the redirected host too

// merge links from Firecrawl AND from the markdown
const md = d.markdown || '';
const rawLinks = [
  ...(d.links || []),
  ...[...md.matchAll(/\]\(([^)\s]+)\)/g)].map(m => m[1])
];

const junk = /(\/(old|blogs?|news|gallery|portfolio|our-work|careers?|jobs|cart|login|checkout|account|wp-admin)(\/|\.|$))|privacy|terms|cookie|giving|charity|donat|sitemap|disclaimer/i;
const skipFile = /\.(jpg|jpeg|png|gif|svg|webp|pdf|css|js|ico|zip)$/i;

const keyOf = p => p
  .replace(/\/index\.(html?|php)$/i, '/')
  .replace(/\.(html?|php)$/i, '')
  .replace(/\/+$/, '') || '/';

// homepage is already scraped, so skip it
const seen = new Set([keyOf(site.path), keyOf(finalUrl.path), '/']);
const urls = [];

for (const raw of rawLinks) {
  const full = resolve(raw, finalUrl);
  if (!full) continue;
  const u = parse(full);
  if (!u || !hosts.has(u.host)) continue;          // same site only

  if (junk.test(u.path) || skipFile.test(u.path)) continue;
  const key = keyOf(u.path);
  if (seen.has(key)) continue;
  seen.add(key);

  urls.push(u.protocol + '://' + u.host + u.path);
}

// safety net: no inner pages found -> keep the workflow running on the homepage
if (!urls.length) {
  return [{ json: { url: lead.website_url, lead_id: lead.lead_id, note: 'no inner links found' } }];
}

return urls.slice(0, MAX_PAGES).map(url => ({ json: { url, lead_id: lead.lead_id } }));

const base = $('build text').first().json;   // lead_id, website_url, website_text
let raw = $input.first().json.output || '';

// strip ```json fences if the model added them
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let info;
try {
  info = JSON.parse(raw);
} catch (e) {
  throw new Error('LLM did not return valid JSON: ' + raw.slice(0, 300));
}

return [{
  json: {
    lead_id: base.lead_id,
    website_url: base.website_url,
    info,                          // the clean structured data
    website_text: base.website_text
  }
}];

const lead = $('On form submission').first().json;   // change the name if yours differs

function clean(md) {
  let t = (md || '');

  // cut the reviews block (only if both markers exist)
  t = t.replace(/What Our Customers Say[\s\S]*?write a review[^\n]*/gi, '');

  return t
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')       // images
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')    // links -> just the text
    .replace(/\*\*/g, '');                      // bold markers
}

// homepage first, then the scraped pages (skip any that errored)
const home = $('Scrape Homepage').first().json;
const pages = [home, ...$input.all().map(i => i.json)]
  .map(j => j.data || j)
  .filter(d => d && d.markdown)
  .map(d => ({
    url: d.metadata?.url || d.metadata?.sourceURL || 'unknown',
    markdown: d.markdown,
    description: d.metadata?.description || ''
  }));

const seen = new Set();
const blocks = [];

for (const p of pages) {
  const kept = clean(p.markdown)
    .split('\n')
    .map(l => l.trim())
    .filter(l => l && l !== '* * *')
    .filter(l => {
      if (seen.has(l)) return false;   // repeated nav/footer/widget lines
      seen.add(l);
      return true;
    });

  blocks.push(`## PAGE: ${p.url}\n` + kept.join('\n'));
}

const website_text = blocks.join('\n\n');
const before = pages.reduce((n, p) => n + p.markdown.length, 0);

return [{
  json: {
    lead_id: lead.lead_id,
    website_url: lead.website_url,
    website_text,
    pages_count: pages.length,
    chars_before: before,
    chars_after: website_text.length
  }
}];

const item = $input.first().json;   // { lead_id, website_url, info, website_text }
const { lead_id, website_url, info } = item;

const chunks = [];

chunks.push({
  content: `Business: ${info.business_name || 'Unknown'}. ${info.short_summary || ''}`,
  type: 'summary'
});

chunks.push({
  content: [
    `Business name: ${info.business_name || 'N/A'}`,
    `Owner: ${info.owner_name || 'N/A'}`,
    `Phone: ${info.phone || 'N/A'}`,
    info.other_phones?.length ? `Other phones: ${info.other_phones.join(', ')}` : null,
    `Email: ${info.email || 'N/A'}`,
    info.addresses?.length ? `Address(es): ${info.addresses.join(' | ')}` : null,
    `Working hours: ${info.working_hours || 'Not listed'}`,
    info.service_areas?.length ? `Service areas: ${info.service_areas.join(', ')}` : null,
    info.languages?.length ? `Languages: ${info.languages.join(', ')}` : null,
    info.years_in_business ? `Years in business: ${info.years_in_business}` : null,
    info.preferred_contact ? `Preferred contact: ${info.preferred_contact}` : null,
    info.pricing_info ? `Pricing: ${info.pricing_info}` : null
  ].filter(Boolean).join('\n'),
  type: 'basic_info'
});

for (const s of (info.services || [])) {
  chunks.push({
    content: `Service: ${s.name}. ${s.description || 'No further details available.'}`,
    type: 'service'
  });
}

return chunks.map(c => ({
  json: {
    pageContent: c.content,
    metadata: { lead_id, website_url, type: c.type }
  }
}));
